import React from 'react';
import { useDroppable } from '@dnd-kit/core';
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable';
import { Task, Category, DailyMeals } from '../types';
import { TaskCard } from './TaskCard';
import { TimeGrid } from './TimeGrid';
import { MealSummary } from './MealSummary';
import { Utensils } from 'lucide-react';

interface DroppableContainerProps {
  id: string;
  title: string;
  tasks: Task[];
  categories: Category[];
  mealPlan?: DailyMeals;
  onEditTask: (task: Task) => void;
  onDeleteTask: (id: string) => void;
  onToggleComplete: (id: string) => void;
  onMoveStage?: (id: string, newStage: 'backlog' | 'staging') => void;
  onEditMealPlan?: () => void;
  onCreateAtTime?: (dateStr: string, startTime: string, duration: number) => void;
  isBacklog?: boolean;
  isToday?: boolean;
  subtitle?: string;
  extraHeader?: React.ReactNode;
  compactMode?: boolean; // For month view
}

export const DroppableContainer: React.FC<DroppableContainerProps> = ({ 
  id, 
  title, 
  tasks, 
  categories,
  mealPlan,
  onEditTask, 
  onDeleteTask, 
  onToggleComplete,
  onMoveStage,
  onEditMealPlan,
  onCreateAtTime,
  isBacklog = false,
  isToday = false,
  subtitle,
  extraHeader,
  compactMode = false
}) => {
  const { setNodeRef, isOver } = useDroppable({ id });

  let displayTasks: Task[] = [];
  let scheduledTasks: Task[] = [];
  let unscheduledTasks: Task[] = [];

  if (compactMode || isBacklog) {
    displayTasks = [...tasks].sort((a, b) => {
      if (a.startTime && b.startTime) return a.startTime.localeCompare(b.startTime);
      if (a.startTime) return -1;
      if (b.startTime) return 1;
      return a.order - b.order;
    });
  } else {
    unscheduledTasks = tasks.filter(t => !t.startTime);
    scheduledTasks = tasks.filter(t => !!t.startTime);
    displayTasks = unscheduledTasks;
  }

  const totalDuration = tasks.filter(t => !t.completed).reduce((acc, t) => acc + t.duration, 0);
  const hours = Math.floor(totalDuration / 60);
  const minutes = totalDuration % 60;
  const timeString = `${hours > 0 ? `${hours}h ` : ''}${minutes}m`;

  const hasMeals = mealPlan && (mealPlan.breakfast.title || mealPlan.lunch.title || mealPlan.dinner.title);

  return (
    <div className={`flex flex-col h-full rounded-xl overflow-hidden border transition-colors ${
      isBacklog 
        ? 'bg-gray-50/50 border-gray-200' 
        : isOver 
          ? 'bg-indigo-50/50 border-indigo-300' 
          : 'bg-gray-100 border-transparent'
    }`}>
      <div className={`p-4 flex-shrink-0 flex justify-between items-center ${isToday ? 'bg-indigo-50/50' : 'bg-transparent'}`}>
         <div className="flex flex-col">
            <h3 className={`font-semibold text-sm uppercase tracking-wide leading-none ${isToday ? 'text-indigo-700' : 'text-gray-600'}`}>
              {title}
            </h3>
            {subtitle && <span className="text-xs text-gray-500 font-medium mt-1">{subtitle}</span>}
         </div>
         <div className="flex items-center gap-2">
            {timeString !== '0m' && (
                <span className="text-[10px] font-mono text-gray-400 bg-white/50 px-1.5 py-0.5 rounded border border-gray-100">
                {timeString}
                </span>
            )}
            {compactMode && onEditMealPlan && (
               <button 
                 onClick={(e) => { e.stopPropagation(); onEditMealPlan(); }}
                 className={`flex items-center gap-0.5 px-1.5 py-0.5 rounded transition-colors ${
                    hasMeals 
                     ? 'bg-green-100 text-green-700 hover:bg-green-200' 
                     : 'text-gray-300 hover:text-green-600 hover:bg-green-50'
                 }`}
                 title="Plan Meals"
               >
                 <Utensils size={10} />
                 <span className="text-[10px] font-bold">+</span>
               </button>
            )}
         </div>
         {extraHeader}
      </div>

      <div className="flex-1 overflow-y-auto scrollbar-thin flex flex-col">
        <div 
          ref={setNodeRef} 
          className={`p-3 space-y-2 min-h-[60px] flex-1 ${!compactMode && (scheduledTasks.length > 0 || isToday) ? 'border-b border-gray-200 pb-4' : ''}`}
        >
           {!isBacklog && !compactMode && (unscheduledTasks.length > 0 || scheduledTasks.length > 0) && (
             <div className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-2">
               To Do
             </div>
           )}

          <SortableContext id={id} items={displayTasks.map(t => t.id)} strategy={verticalListSortingStrategy}>
            {displayTasks.length === 0 && isBacklog ? (
              <div className="h-32 flex flex-col items-center justify-center text-gray-300 border-2 border-dashed border-gray-200 rounded-lg m-2">
                <span className="text-sm">Empty Backlog</span>
              </div>
            ) : displayTasks.length === 0 && !isBacklog && scheduledTasks.length === 0 ? (
                <div className="h-20 flex flex-col items-center justify-center text-gray-300 border-2 border-dashed border-gray-200 rounded-lg">
                  <span className="text-xs">Empty</span>
                </div>
            ) : (
              displayTasks.map(task => (
                <TaskCard key={task.id} task={task} categoryData={categories.find(c => c.id === task.categoryId)} onEdit={onEditTask} onDelete={onDeleteTask} onToggleComplete={onToggleComplete} onMoveStage={onMoveStage} />
              ))
            )}
          </SortableContext>
        </div>

        {!isBacklog && !compactMode && (
          <div className="relative border-t border-gray-100 bg-white/50">
            <div className="p-3 sticky top-0 bg-white/95 backdrop-blur z-10 border-b border-gray-100 flex justify-between items-center">
               <div className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Schedule</div>
               <span className="text-[9px] text-gray-300">Click & Drag to Create</span>
            </div>
            <TimeGrid dateStr={id} tasks={scheduledTasks} onEditTask={onEditTask} onCreateAtTime={onCreateAtTime} />
          </div>
        )}
      </div>

      {!isBacklog && !compactMode && onEditMealPlan && (
        <div className="flex-shrink-0">
          <MealSummary meals={mealPlan} onClick={onEditMealPlan} compactMode={compactMode} />
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { useDroppable, useDraggable } from '@dnd-kit/core';
import { Task } from '../types';
import { Clock, Plus } from 'lucide-react';

const HOURS = Array.from({ length: 17 }, (_, i) => i + 6); // 6 AM to 10 PM
const SLOT_HEIGHT = 64; // px

interface TimeGridProps {
  dateStr: string;
  tasks: Task[];
  onEditTask: (task: Task) => void;
  onCreateAtTime?: (dateStr: string, startTime: string, duration: number) => void;
}

interface TimeSlotProps {
  dateStr: string;
  hour: number;
  onMouseDown: (hour: number, minutes: number) => void;
  children?: React.ReactNode;
}

const TimeSlot: React.FC<TimeSlotProps> = ({ dateStr, hour, onMouseDown, children }) => {
  const slotId = `${dateStr}::${hour.toString().padStart(2, '0')}`;
  const { setNodeRef, isOver } = useDroppable({ id: slotId });

  const handleSlotMouseDown = (e: React.MouseEvent) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const offsetY = e.clientY - rect.top;
    const minutes = Math.floor((offsetY / SLOT_HEIGHT) * 60);
    // Snap to 15m intervals for better UX
    const snappedMinutes = Math.floor(minutes / 15) * 15;
    onMouseDown(hour, snappedMinutes);
  };

  return (
    <div 
      ref={setNodeRef}
      onMouseDown={handleSlotMouseDown}
      className={`relative h-16 border-b border-gray-100 flex transition-colors ${
        isOver ? 'bg-indigo-50/80' : 'hover:bg-gray-50/30'
      } cursor-crosshair`}
    >
      <div className="w-12 flex-shrink-0 text-[10px] text-gray-400 p-1 text-right border-r border-gray-100 pr-2 pt-1 font-mono select-none">
        {hour}:00
      </div>
      <div className="flex-1 relative">
        <div className="absolute top-1/2 left-0 w-full border-t border-gray-50 border-dashed pointer-events-none"></div>
        {children}
      </div>
    </div>
  );
};

const GridTask: React.FC<{ task: Task; onEdit: (t: Task) => void }> = ({ task, onEdit }) => {
  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
    id: task.id,
    data: { type: 'Task', task, fromGrid: true },
  });

  const heightPx = Math.max(24, (task.duration / 60) * SLOT_HEIGHT);
  const [_, minStr] = (task.startTime || "00:00").split(':');
  const minutes = parseInt(minStr, 10);
  const topOffset = (minutes / 60) * SLOT_HEIGHT;

  const style = transform ? {
    transform: `translate3d(${transform.x}px, ${transform.y}px, 0)`,
    zIndex: 50,
  } : undefined;

  if (isDragging) return null;

  return (
    <div
      ref={setNodeRef}
      {...listeners}
      {...attributes}
      onClick={(e) => { e.stopPropagation(); onEdit(task); }}
      style={{ ...style, height: `${heightPx}px`, top: `${topOffset}px` }}
      className={`absolute left-1 right-1 rounded px-2 py-1 text-xs border shadow-sm cursor-grab active:cursor-grabbing flex flex-col justify-start overflow-hidden hover:brightness-95 transition-all z-10 ${
        task.completed ? 'bg-gray-100 text-gray-500 border-gray-200' : 'bg-indigo-100 text-indigo-800 border-indigo-200'
      }`}
    >
      <div className="font-semibold truncate leading-tight">{task.title}</div>
      <div className="text-[9px] opacity-80 flex items-center gap-1"><Clock size={8} />{task.duration}m</div>
    </div>
  );
};

export const TimeGrid: React.FC<TimeGridProps> = ({ dateStr, tasks, onEditTask, onCreateAtTime }) => {
  const [selection, setSelection] = useState<{ startHour: number; startMin: number; currentHour: number; currentMin: number } | null>(null);
  const gridRef = useRef<HTMLDivElement>(null);

  const handleMouseDown = (hour: number, minutes: number) => {
    setSelection({ startHour: hour, startMin: minutes, currentHour: hour, currentMin: minutes + 30 });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!selection || !gridRef.current) return;
    const rect = gridRef.current.getBoundingClientRect();
    const offsetY = e.clientY - rect.top;

    // Total minutes since 6:00
    const totalMinutes = (offsetY / SLOT_HEIGHT) * 60;
    const hour = Math.floor(totalMinutes / 60) + 6;
    const min = Math.floor((totalMinutes % 60) / 15) * 15;

    setSelection(prev => prev ? { ...prev, currentHour: hour, currentMin: min } : null);
  };

  const handleMouseUp = () => {
    if (!selection || !onCreateAtTime) {
      setSelection(null);
      return;
    }

    const startTotal = selection.startHour * 60 + selection.startMin;
    const currentTotal = selection.currentHour * 60 + selection.currentMin;

    const startTime = `${selection.startHour.toString().padStart(2, '0')}:${selection.startMin.toString().padStart(2, '0')}`;
    const duration = Math.max(15, currentTotal - startTotal);

    onCreateAtTime(dateStr, startTime, duration);
    setSelection(null);
  };

  useEffect(() => {
    if (selection) {
      const up = () => handleMouseUp();
      window.addEventListener('mouseup', up);
      return () => window.removeEventListener('mouseup', up);
    }
  }, [selection]);

  const renderSelection = () => {
    if (!selection) return null;
    const startTotal = selection.startHour * 60 + selection.startMin;
    const currentTotal = selection.currentHour * 60 + selection.currentMin;

    const top = ((startTotal - 6 * 60) / 60) * SLOT_HEIGHT;
    const height = Math.max(15, (currentTotal - startTotal) / 60 * SLOT_HEIGHT);

    return (
      <div 
        style={{ top: `${top}px`, height: `${height}px` }}
        className="absolute left-14 right-1 bg-indigo-500/20 border-2 border-indigo-400 border-dashed rounded-lg z-20 pointer-events-none flex items-center justify-center"
      >
        <div className="bg-indigo-600 text-white text-[10px] font-bold px-1.5 py-0.5 rounded flex items-center gap-1">
           <Plus size={10} /> New Task ({Math.round(currentTotal - startTotal)}m)
        </div>
      </div>
    );
  };

  return (
    <div 
      ref={gridRef} 
      className="pb-4 select-none relative"
      onMouseMove={handleMouseMove}
    >
      {renderSelection()}
      {HOURS.map(hour => {
        const hourPrefix = hour.toString().padStart(2, '0');
        const tasksInHour = tasks.filter(t => t.startTime?.startsWith(`${hourPrefix}:`));
        return (
          <TimeSlot key={hour} dateStr={dateStr} hour={hour} onMouseDown={handleMouseDown}>
            {tasksInHour.map(task => (
              <GridTask key={task.id} task={task} onEdit={onEditTask} />
            ))}
          </TimeSlot>
        );
      })}
    </div>
  );
};

