import React, { useState, useEffect, useRef } from 'react';
import { JournalEntry } from '../types';
import { ChevronLeft, Maximize2, Minimize2, Check, Copy } from 'lucide-react';

interface BasicEntryEditorProps {
  entry: JournalEntry;
  onSave: (content: string, title: string) => void;
  onClone: () => void;
  onExit: () => void;
}

export const BasicEntryEditor: React.FC<BasicEntryEditorProps> = ({ entry, onSave, onClone, onExit }) => {
  const [content, setContent] = useState(entry.content);
  const [title, setTitle] = useState(entry.title);
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [saving, setSaving] = useState(false);
  const saveTimeout = useRef<any | null>(null);

  // Sync state if entry changes (e.g. from switching entries)
  useEffect(() => {
    setContent(entry.content);
    setTitle(entry.title);
  }, [entry.id]);

  useEffect(() => {
    if (content !== entry.content || title !== entry.title) {
      if (saveTimeout.current) clearTimeout(saveTimeout.current);
      setSaving(true);
      saveTimeout.current = setTimeout(() => {
        onSave(content, title);
        setSaving(false);
      }, 1000);
    }
  }, [content, title]);

  return (
    <div className={`flex flex-col h-full bg-white transition-all duration-500 ${isFullScreen ? 'fixed inset-0 z-[100]' : 'relative'}`}>
      <div className="h-16 border-b border-slate-100 flex items-center justify-between px-8 bg-white/80 backdrop-blur-sm sticky top-0 z-10">
        <div className="flex items-center gap-6 flex-1">
          <button 
            onClick={onExit}
            className="p-2 hover:bg-slate-100 rounded-full text-slate-400 hover:text-slate-900 transition-all flex-shrink-0"
          >
            <ChevronLeft size={24} />
          </button>
          <div className="flex flex-col flex-1 max-w-xl">
            <input 
              type="text" 
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="text-sm font-black text-slate-900 bg-transparent border-none outline-none focus:ring-0 p-0"
              placeholder="Enter title..."
            />
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
              Drafting • {new Date(entry.date).toLocaleDateString()}
            </span>
          </div>
        </div>

        <div className="flex items-center gap-2">
           <div className="mr-4">
              {saving ? (
                <div className="flex items-center gap-2 text-indigo-500 text-[10px] font-black uppercase">
                    <div className="w-1 h-1 bg-indigo-500 rounded-full animate-ping"></div>
                    Saving...
                </div>
              ) : (
                <div className="flex items-center gap-1 text-emerald-500 text-[10px] font-black uppercase">
                    <Check size={12} />
                    Synced
                </div>
              )}
           </div>

           <button 
             onClick={onClone}
             title="Duplicate Entry"
             className="p-2 hover:bg-slate-100 rounded-lg text-slate-400 hover:text-indigo-600 transition-all"
           >
             <Copy size={20} />
           </button>

           <button 
             onClick={() => setIsFullScreen(!isFullScreen)}
             className="p-2 hover:bg-slate-100 rounded-lg text-slate-400 hover:text-slate-900 transition-all"
           >
             {isFullScreen ? <Minimize2 size={20} /> : <Maximize2 size={20} />}
           </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col items-center overflow-y-auto scrollbar-thin py-20 px-4">
        <textarea 
          autoFocus
          className="w-full max-w-3xl flex-1 bg-transparent text-xl font-medium leading-relaxed text-slate-800 placeholder:text-slate-200 border-none outline-none focus:ring-0 resize-none min-h-[500px]"
          placeholder="Start writing your thoughts here..."
          value={content}
          onChange={e => setContent(e.target.value)}
        />
        <div className="w-full max-w-3xl mt-20 pt-10 border-t border-slate-50 flex justify-between items-center text-[10px] font-black text-slate-300 uppercase tracking-widest">
           <span>{content.trim() ? content.trim().split(/\s+/).length : 0} Words</span>
           <span>Character Count: {content.length}</span>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { Task } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const optimizeSchedule = async (
  currentTasks: Task[],
  availableDates: string[]
): Promise<Task[]> => {
  const activeTasks = currentTasks.filter(t => !t.completed);
  const now = new Date();
  const currentTimeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
  const todayStr = now.toISOString().split('T')[0];

  const prompt = `
    You are an expert productivity assistant (Sunsama/Akiflow style). I have a list of tasks that need scheduling.
    Today's Date: ${todayStr}
    Current Time: ${currentTimeStr}
    Available Planning Window: ${availableDates.join(', ')}

    Rules for Scheduling:
    1. Distribute tasks across the window. Do not overfill a single day (max 400 mins/day).
    2. Suggest a START TIME (HH:mm) for every task you schedule. 
    3. If scheduling for today (${todayStr}), the startTime MUST be after ${currentTimeStr}.
    4. Prioritize 'staging' stage and 'high' priority tasks for earlier slots.
    5. Group similar tasks if possible.
    6. If a task already has a startTime, you may keep it or move it if it helps the overall flow.

    Return a JSON object with an 'updates' array. 
    Each update MUST have: id, scheduledDate (YYYY-MM-DD), startTime (HH:mm), and order (integer).

    Current Task Backlog/Active:
    ${JSON.stringify(activeTasks.map(({id, title, priority, duration, scheduledDate, startTime, stage}) => ({id, title, priority, duration, scheduledDate, startTime, stage})))}
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            updates: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING },
                  scheduledDate: { type: Type.STRING },
                  startTime: { type: Type.STRING },
                  order: { type: Type.NUMBER }
                },
                required: ["id", "scheduledDate", "startTime", "order"]
              }
            }
          },
          required: ["updates"]
        }
      }
    });

    const jsonText = response.text;
    if (!jsonText) return currentTasks;

    const result = JSON.parse(jsonText) as { updates: { id: string, scheduledDate: string, startTime: string, order: number }[] };

    const newTasks = [...currentTasks];
    result.updates.forEach(update => {
      const index = newTasks.findIndex(t => t.id === update.id);
      if (index !== -1) {
        newTasks[index] = {
          ...newTasks[index],
          scheduledDate: update.scheduledDate,
          startTime: update.startTime,
          order: update.order,
          stage: 'staging'
        };
      }
    });

    return newTasks;

  } catch (error) {
    console.error("Gemini Scheduling Error:", error);
    return currentTasks;
  }
};

export const suggestTaskTime = async (
  task: Partial<Task>,
  existingTasks: Task[],
  targetDate: string
): Promise<{ scheduledDate: string; startTime: string }> => {
  const scheduledOnDay = existingTasks.filter(t => t.scheduledDate === targetDate && t.startTime);
  const now = new Date();
  const isToday = targetDate === now.toISOString().split('T')[0];
  const minTime = isToday ? `${(now.getHours() + 1).toString().padStart(2, '0')}:00` : "08:00";

  const prompt = `
    Find the best available time slot for a new task on ${targetDate}.
    Task: "${task.title}" (${task.duration} mins, ${task.priority} priority).
    Constraint: If today, must be after ${minTime}.
    Existing schedule: ${JSON.stringify(scheduledOnDay.map(t => ({ title: t.title, start: t.startTime, duration: t.duration })))}
    Return startTime in HH:mm.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            startTime: { type: Type.STRING }
          },
          required: ["startTime"]
        }
      }
    });

    const result = JSON.parse(response.text || '{"startTime":"09:00"}');
    return {
      scheduledDate: targetDate,
      startTime: result.startTime
    };
  } catch (error) {
    return { scheduledDate: targetDate, startTime: "09:00" };
  }
};

import React, { useState } from 'react';
import { useDroppable } from '@dnd-kit/core';
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable';
import { Task, Category, DailyMeals } from '../types';
import { TaskCard } from './TaskCard';
import { TimeGrid } from './TimeGrid';
import { MealSummary } from './MealSummary';
import { Utensils, ChevronDown, ChevronUp, Layers } from 'lucide-react';

interface DroppableContainerProps {
  id: string;
  title: string;
  tasks: Task[];
  categories: Category[];
  mealPlan?: DailyMeals;
  onEditTask: (task: Task) => void;
  onDeleteTask: (id: string) => void;
  onToggleComplete: (id: string) => void;
  onMoveStage?: (id: string, newStage: 'backlog' | 'staging') => void;
  onEditMealPlan?: () => void;
  onCreateAtTime?: (dateStr: string, startTime: string, duration: number) => void;
  isBacklog?: boolean;
  isToday?: boolean;
  subtitle?: string;
  extraHeader?: React.ReactNode;
  compactMode?: boolean;
}

export const DroppableContainer: React.FC<DroppableContainerProps> = ({ 
  id, 
  title, 
  tasks, 
  categories,
  mealPlan,
  onEditTask, 
  onDeleteTask, 
  onToggleComplete,
  onMoveStage,
  onEditMealPlan,
  onCreateAtTime,
  isBacklog = false,
  isToday = false,
  subtitle,
  extraHeader,
  compactMode = false
}) => {
  const { setNodeRef, isOver } = useDroppable({ id });
  const [allDayExpanded, setAllDayExpanded] = useState(false);

  let displayTasks: Task[] = [];
  let scheduledTasks: Task[] = [];
  let allDayTasks: Task[] = [];

  if (compactMode || isBacklog) {
    displayTasks = [...tasks].sort((a, b) => {
      if (a.startTime && b.startTime) return a.startTime.localeCompare(b.startTime);
      if (a.startTime) return -1;
      if (b.startTime) return 1;
      return a.order - b.order;
    });
  } else {
    allDayTasks = tasks.filter(t => !t.startTime).sort((a,b) => a.order - b.order);
    scheduledTasks = tasks.filter(t => !!t.startTime);
    displayTasks = allDayTasks;
  }

  const totalDuration = tasks.filter(t => !t.completed).reduce((acc, t) => acc + t.duration, 0);
  const hours = Math.floor(totalDuration / 60);
  const minutes = totalDuration % 60;
  const timeString = `${hours > 0 ? `${hours}h ` : ''}${minutes}m`;

  const hasMeals = mealPlan && (mealPlan.breakfast.title || mealPlan.lunch.title || mealPlan.dinner.title);

  return (
    <div className={`flex flex-col h-full rounded-xl overflow-hidden border-2 transition-colors ${
      isBacklog 
        ? 'bg-slate-100 border-slate-300' 
        : isOver 
          ? 'bg-indigo-100/50 border-indigo-500' 
          : 'bg-slate-50 border-transparent'
    }`}>
      <div className={`p-4 flex-shrink-0 flex justify-between items-center border-b ${isToday ? 'bg-indigo-100/30 border-indigo-200' : 'bg-slate-100 border-slate-200'}`}>
         <div className="flex flex-col">
            <h3 className={`font-black text-sm uppercase tracking-widest leading-none ${isToday ? 'text-indigo-900' : 'text-slate-700'}`}>
              {title}
            </h3>
            {subtitle && <span className="text-[11px] text-slate-500 font-black mt-1 uppercase tracking-wider">{subtitle}</span>}
         </div>
         <div className="flex items-center gap-2">
            {timeString !== '0m' && (
                <span className="text-[10px] font-black font-mono text-slate-600 bg-white px-2 py-0.5 rounded border border-slate-300 shadow-sm">
                {timeString}
                </span>
            )}
            {compactMode && onEditMealPlan && (
               <button 
                 onClick={(e) => { e.stopPropagation(); onEditMealPlan(); }}
                 className={`flex items-center gap-0.5 px-2 py-0.5 rounded border-2 transition-colors font-black ${
                    hasMeals 
                     ? 'bg-green-600 text-white border-green-700 hover:bg-green-700' 
                     : 'text-slate-400 border-slate-300 hover:text-green-700 hover:bg-green-50 hover:border-green-600'
                 }`}
               >
                 <Utensils size={10} strokeWidth={3} />
                 <span className="text-[10px]">+</span>
               </button>
            )}
         </div>
         {extraHeader}
      </div>

      <div className="flex-1 overflow-y-auto scrollbar-thin flex flex-col">
        {!isBacklog && !compactMode ? (
          <div className="flex-shrink-0 border-b border-slate-200 bg-white/50">
            <button 
              onClick={() => setAllDayExpanded(!allDayExpanded)}
              className="w-full px-4 py-2 flex items-center justify-between text-[11px] font-black text-slate-500 hover:text-indigo-600 transition-colors bg-slate-100/40"
            >
              <div className="flex items-center gap-2 uppercase tracking-widest">
                <Layers size={14} className="text-slate-400" />
                <span>All Day Tasks ({allDayTasks.length})</span>
              </div>
              {allDayTasks.length > 0 && (allDayExpanded ? <ChevronUp size={14} /> : <ChevronDown size={14} />)}
            </button>

            <div 
              ref={setNodeRef}
              className={`p-3 space-y-2 overflow-hidden transition-all duration-300 ease-in-out ${
                allDayExpanded || allDayTasks.length === 0 ? 'max-h-[1000px] opacity-100' : 'max-h-24 overflow-hidden mask-fade'
              }`}
              style={(!allDayExpanded && allDayTasks.length > 1) ? { maskImage: 'linear-gradient(to bottom, black 50%, transparent 100%)', WebkitMaskImage: 'linear-gradient(to bottom, black 50%, transparent 100%)' } : {}}
            >
              <SortableContext id={id} items={allDayTasks.map(t => t.id)} strategy={verticalListSortingStrategy}>
                {allDayTasks.length === 0 ? (
                  <div className="py-2 text-center text-[10px] font-black uppercase text-slate-300 tracking-widest">No All-Day Tasks</div>
                ) : (
                  allDayTasks.map(task => (
                    <TaskCard key={task.id} task={task} categoryData={categories.find(c => c.id === task.categoryId)} onEdit={onEditTask} onDelete={onDeleteTask} onToggleComplete={onToggleComplete} onMoveStage={onMoveStage} />
                  ))
                )}
              </SortableContext>
            </div>
          </div>
        ) : (
          <div ref={setNodeRef} className="p-3 space-y-2 min-h-[60px] flex-1">
            <SortableContext id={id} items={displayTasks.map(t => t.id)} strategy={verticalListSortingStrategy}>
              {displayTasks.length === 0 ? (
                <div className="h-32 flex flex-col items-center justify-center text-slate-400 bg-slate-200/50 border-2 border-dashed border-slate-300 rounded-xl m-2">
                  <span className="text-xs font-bold uppercase tracking-widest">{isBacklog ? 'Empty Backlog' : 'No Tasks'}</span>
                </div>
              ) : (
                displayTasks.map(task => (
                  <TaskCard key={task.id} task={task} categoryData={categories.find(c => c.id === task.categoryId)} onEdit={onEditTask} onDelete={onDeleteTask} onToggleComplete={onToggleComplete} onMoveStage={onMoveStage} />
                ))
              )}
            </SortableContext>
          </div>
        )}

        {!isBacklog && !compactMode && (
          <div className="relative bg-white flex-1 min-h-[400px]">
            <TimeGrid dateStr={id} tasks={scheduledTasks} onEditTask={onEditTask} onCreateAtTime={onCreateAtTime} />
          </div>
        )}
      </div>

      {!isBacklog && !compactMode && onEditMealPlan && (
        <div className="flex-shrink-0 border-t border-slate-200 shadow-lg">
          <MealSummary meals={mealPlan} onClick={onEditMealPlan} compactMode={compactMode} />
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, Type } from "@google/genai";
import { RitualProposedChanges, Task, Message, JournalEntry } from '../types';
import { ChevronLeft, Send, Sparkles, Loader2, Calendar, Check, X, AlertTriangle, Utensils, Plus } from 'lucide-react';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

interface MorningRitualProps {
  onFinish: (changes: RitualProposedChanges, journalEntry: Partial<JournalEntry>) => void;
  onCancel: () => void;
  currentTasks: Task[];
}

export const MorningRitual: React.FC<MorningRitualProps> = ({ onFinish, onCancel, currentTasks }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [chat, setChat] = useState<any>(null);
  const [proposedChanges, setProposedChanges] = useState<RitualProposedChanges | null>(null);
  const [view, setView] = useState<'chat' | 'confirmation'>('chat');
  const [isFinalizing, setIsFinalizing] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const todayStr = new Date().toISOString().split('T')[0];
    const initChat = async () => {
      const model = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: `You are a mindful productivity coach. 
          Conduct a "Morning Ritual" conversation. Today's date is ${todayStr}.
          1. Reflect on yesterday's wins and misses.
          2. Plan today's schedule. 
          3. Crucially: If a task should happen today, assign it a scheduledDate of ${todayStr}.
          4. Suggest specific start times (HH:mm) for tasks discussed so they appear in the day's timeline.

          Current Calendar Context: ${JSON.stringify(currentTasks.map(t => ({ id: t.id, title: t.title, completed: t.completed, date: t.scheduledDate, time: t.startTime })))}

          After the user indicates they are done planning, output a JSON block wrapped in triple backticks with the tag "PROPOSAL" that follows this schema:
          {
            "tasksToAdd": [{"title": string, "duration": number, "priority": "high"|"medium"|"low", "scheduledDate": "YYYY-MM-DD" | null, "startTime": "HH:mm" | null}],
            "tasksToComplete": [id strings],
            "tasksToRemove": [id strings],
            "mealsToUpdate": { "date": "YYYY-MM-DD", "meals": { "breakfast": {"title": string, "ingredients": string}, "lunch": {"title": string, "ingredients": string}, "dinner": {"title": string, "ingredients": string}, "snacks": {"title": string, "ingredients": string} } }
          }
          Only output the proposal when the user is ready to finalize.`
        }
      });
      setChat(model);

      const response = await model.sendMessage({ message: "Hello! Let's start our morning ritual. How did yesterday go for you?" });
      setMessages([{ role: 'model', text: response.text }]);
    };
    initChat();
  }, []);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || loading || !chat) return;

    const userMessage: Message = { role: 'user', text: input };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setLoading(true);

    try {
      const response = await chat.sendMessage({ message: input });
      const text = response.text;

      if (text.includes('PROPOSAL')) {
        const match = text.match(/```json\s*PROPOSAL\s*([\s\S]*?)```/i) || text.match(/```PROPOSAL\s*([\s\S]*?)```/i);
        if (match) {
          try {
            const proposal = JSON.parse(match[1]);
            setProposedChanges(proposal);
            setView('confirmation');
          } catch (e) {
            console.error("JSON parse error for proposal", e);
          }
        }
      }

      setMessages(prev => [...prev, { role: 'model', text: text.split('```')[0].trim() }]);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleFinalize = async () => {
    if (!proposedChanges) return;
    setIsFinalizing(true);

    try {
      const summaryResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Summarize the following planning session transcript in 2-3 concise, insightful sentences for a journal entry:\n\n${messages.map(m => `${m.role.toUpperCase()}: ${m.text}`).join('\n')}`,
      });

      const journalEntry: Partial<JournalEntry> = {
        title: `Morning Ritual - ${new Date().toLocaleDateString()}`,
        content: summaryResponse.text || "Daily planning session completed with AI guidance.",
        transcript: messages,
        type: 'ritual',
        date: new Date().toISOString()
      };

      onFinish(proposedChanges, journalEntry);
    } catch (error) {
      console.error("Error generating ritual summary:", error);
      onFinish(proposedChanges, {
        title: `Morning Ritual - ${new Date().toLocaleDateString()}`,
        content: "Completed ritual session.",
        transcript: messages,
        type: 'ritual',
        date: new Date().toISOString()
      });
    } finally {
      setIsFinalizing(false);
    }
  };

  if (view === 'confirmation' && proposedChanges) {
    return (
      <div className="flex flex-col h-full bg-slate-50">
        <div className="h-16 border-b border-slate-200 bg-white flex items-center px-8 shadow-sm">
           <h2 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center gap-2">
             <Check className="text-emerald-500" />
             Review Ritual Adjustments
           </h2>
        </div>
        <div className="flex-1 overflow-y-auto p-8 max-w-3xl mx-auto w-full">
           <div className="bg-white rounded-3xl border border-slate-200 shadow-xl p-8 space-y-8">
              <section>
                 <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <Plus size={16} className="text-indigo-500" /> Tasks to Add
                 </h3>
                 <div className="space-y-3">
                    {proposedChanges.tasksToAdd.map((t, i) => (
                       <div key={i} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                          <div className="flex flex-col">
                            <span className="font-bold text-slate-800">{t.title}</span>
                            {t.startTime && <span className="text-[10px] font-black text-indigo-600 uppercase">Starts at {t.startTime}</span>}
                          </div>
                          <span className="text-[10px] font-black text-indigo-600 bg-indigo-50 px-2 py-1 rounded-full">{t.duration}m</span>
                       </div>
                    ))}
                    {proposedChanges.tasksToAdd.length === 0 && <p className="text-xs text-slate-400 italic">No tasks added.</p>}
                 </div>
              </section>

              <section>
                 <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <Check size={16} className="text-emerald-500" /> Mark as Complete
                 </h3>
                 <div className="space-y-3">
                    {proposedChanges.tasksToComplete.map(id => {
                      const task = currentTasks.find(ct => ct.id === id);
                      return (
                        <div key={id} className="flex items-center justify-between p-4 bg-emerald-50/50 rounded-2xl border border-emerald-100">
                           <span className="font-bold text-emerald-900">{task?.title || 'Unknown Task'}</span>
                        </div>
                      );
                    })}
                    {proposedChanges.tasksToComplete.length === 0 && <p className="text-xs text-slate-400 italic">No tasks completed.</p>}
                 </div>
              </section>

              <section>
                 <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <X size={16} className="text-rose-500" /> Remove from Schedule
                 </h3>
                 <div className="space-y-3">
                    {proposedChanges.tasksToRemove.map(id => {
                       const task = currentTasks.find(ct => ct.id === id);
                       return (
                        <div key={id} className="flex items-center justify-between p-4 bg-rose-50/50 rounded-2xl border border-rose-100">
                           <span className="font-bold text-rose-900">{task?.title || 'Unknown Task'}</span>
                        </div>
                      );
                    })}
                    {proposedChanges.tasksToRemove.length === 0 && <p className="text-xs text-slate-400 italic">No tasks removed.</p>}
                 </div>
              </section>

              {proposedChanges.mealsToUpdate && (
                <section>
                  <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                      <Utensils size={16} className="text-green-500" /> Nutrition Update
                  </h3>
                  <div className="grid grid-cols-2 gap-4">
                     {Object.entries(proposedChanges.mealsToUpdate.meals).map(([type, meal]: [any, any]) => (
                        <div key={type} className="p-4 bg-green-50/30 rounded-2xl border border-green-100">
                           <span className="text-[10px] font-black text-green-600 uppercase block mb-1">{type}</span>
                           <span className="font-bold text-slate-800 text-sm">{meal?.title || 'No change'}</span>
                        </div>
                     ))}
                  </div>
                </section>
              )}
           </div>
        </div>
        <div className="h-20 border-t border-slate-200 bg-white px-8 flex items-center justify-end gap-4 shadow-inner">
           <button 
             disabled={isFinalizing}
             onClick={() => setView('chat')}
             className="px-6 py-2.5 text-sm font-black text-slate-500 hover:bg-slate-100 rounded-xl transition-all disabled:opacity-50"
           >
             Go Back to Chat
           </button>
           <button 
             disabled={isFinalizing}
             onClick={handleFinalize}
             className="px-10 py-2.5 text-sm font-black text-white bg-indigo-600 hover:bg-indigo-700 rounded-xl shadow-lg shadow-indigo-100 transition-all flex items-center gap-2 disabled:opacity-50"
           >
             {isFinalizing ? <Loader2 size={16} className="animate-spin" /> : <Sparkles size={16} />} 
             {isFinalizing ? "Saving Ritual..." : "Finalize Ritual"}
           </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-white relative overflow-hidden">
      <div className="h-16 border-b border-slate-100 flex items-center justify-between px-8 bg-white/80 backdrop-blur-sm sticky top-0 z-20">
        <div className="flex items-center gap-6">
          <button onClick={onCancel} className="p-2 hover:bg-slate-100 rounded-full text-slate-400 hover:text-slate-900 transition-all">
            <ChevronLeft size={24} />
          </button>
          <div className="flex flex-col">
            <h2 className="text-sm font-black text-slate-900 tracking-tight flex items-center gap-2">
               Morning Ritual
               <span className="bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded-full text-[9px] border border-indigo-100 uppercase font-black">AI Guided</span>
            </h2>
          </div>
        </div>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto scrollbar-thin p-8 flex flex-col gap-6 max-w-4xl mx-auto w-full">
         <div className="flex flex-col gap-6 py-12">
            {messages.map((m, i) => (
               <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-in slide-in-from-bottom-2 duration-300`}>
                  <div className={`max-w-[80%] p-6 rounded-3xl font-medium leading-relaxed ${m.role === 'user' ? 'bg-indigo-600 text-white rounded-tr-none shadow-xl shadow-indigo-100' : 'bg-slate-100 text-slate-800 rounded-tl-none border border-slate-200'}`}>
                     {m.text}
                  </div>
               </div>
            ))}
            {loading && (
               <div className="flex justify-start">
                  <div className="bg-slate-50 p-6 rounded-3xl rounded-tl-none border border-slate-200 flex items-center gap-3 text-slate-400 italic text-sm">
                     <Loader2 className="animate-spin" size={16} />
                     Reflecting...
                  </div>
               </div>
            )}
         </div>
      </div>

      <div className="p-8 border-t border-slate-100 bg-white shadow-2xl">
         <div className="max-w-4xl mx-auto flex gap-4">
            <input 
              type="text" 
              placeholder="Tell your coach about yesterday or today..." 
              className="flex-1 px-6 py-4 bg-slate-100 border-none rounded-2xl outline-none focus:ring-4 focus:ring-indigo-500/10 font-medium transition-all"
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleSend()}
            />
            <button 
              onClick={handleSend}
              disabled={loading}
              className="w-14 h-14 bg-indigo-600 text-white rounded-2xl flex items-center justify-center hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200 disabled:opacity-50"
            >
               <Send size={24} />
            </button>
         </div>
         <p className="text-center mt-4 text-[10px] font-black text-slate-300 uppercase tracking-widest">Type "I'm finished" when you're done planning.</p>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  DndContext, 
  DragOverlay, 
  closestCorners, 
  KeyboardSensor, 
  PointerSensor, 
  useSensor, 
  useSensors,
  DragStartEvent,
  DragEndEvent,
  useDroppable,
} from '@dnd-kit/core';
import { arrayMove, sortableKeyboardCoordinates } from '@dnd-kit/sortable';
import { format, addDays, startOfToday, parseISO, isSameDay, startOfMonth, endOfMonth, startOfWeek, endOfWeek, eachDayOfInterval, addMonths, addWeeks } from 'date-fns';
import { Plus, Sparkles, Calendar as CalendarIcon, Loader2, CalendarDays, Grid3X3, List, ChevronLeft, ChevronRight, Inbox, Layers, Utensils, ShoppingCart, Repeat, LayoutDashboard, Calendar, PenTool } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';

import { Task, TasksState, Category, DailyMeals, Recipe, ShoppingCategory, ShoppingItem, JournalEntry, RitualProposedChanges } from './types';
import { TaskModal } from './components/TaskModal';
import { MealModal } from './components/MealModal';
import { MealDashboard } from './components/MealDashboard';
import { ShoppingDashboard } from './components/ShoppingDashboard';
import { RecurrenceDashboard } from './components/RecurrenceDashboard';
import { DroppableContainer } from './components/DroppableContainer';
import { TodaySidebar } from './components/TodaySidebar';
import { TaskCard } from './components/TaskCard';
import { JournalDashboard } from './components/JournalDashboard';
import { optimizeSchedule } from './services/geminiService';

const TAB_BACKLOG = 'tab-backlog';
const TAB_STAGING = 'tab-staging';

const DroppableTab = ({ id, active, onClick, children, icon: Icon }: any) => {
  const { setNodeRef, isOver } = useDroppable({ id });
  return (
    <button
      ref={setNodeRef}
      onClick={onClick}
      className={`flex-1 pb-3 text-sm font-semibold border-b-2 transition-colors flex items-center justify-center gap-2 ${
        active 
          ? 'border-indigo-600 text-indigo-700' 
          : isOver
            ? 'border-indigo-400 text-indigo-500 bg-indigo-50/50'
            : 'border-transparent text-slate-500 hover:text-slate-700'
      }`}
    >
      <Icon size={16} />
      {children}
    </button>
  );
};

export default function App() {
  const [categories, setCategories] = useState<Category[]>([
    { id: 'cat1', name: 'Work', color: 'blue' },
    { id: 'cat2', name: 'Personal', color: 'green' },
    { id: 'cat3', name: 'House', color: 'orange' },
  ]);

  const [tasks, setTasks] = useState<TasksState>(() => {
    return [
      { id: '1', title: 'Review Q4 Roadmap', description: 'Check with product team', scheduledDate: null, stage: 'staging', duration: 45, priority: 'high', completed: false, order: 0, categoryId: 'cat1' },
      { id: '2', title: 'Email Marketing Draft', description: 'Focus on new features', scheduledDate: format(new Date(), 'yyyy-MM-dd'), stage: 'staging', duration: 60, priority: 'medium', completed: false, order: 0, categoryId: 'cat1' },
      { id: '3', title: 'Daily Workout', description: '30 mins cardio', scheduledDate: format(new Date(), 'yyyy-MM-dd'), startTime: '08:00', stage: 'staging', duration: 30, priority: 'medium', completed: false, order: 1, categoryId: 'cat2', recurrence: 'daily', recurrenceGroupId: 'rg1' },
      { id: '4', title: 'Team Sync', description: 'Daily standup', scheduledDate: format(new Date(), 'yyyy-MM-dd'), startTime: '10:00', stage: 'staging', duration: 15, priority: 'low', completed: true, order: 1, categoryId: 'cat1' },
      { id: '5', title: 'Client Call', description: 'Discuss project scope', scheduledDate: format(new Date(), 'yyyy-MM-dd'), startTime: '14:00', stage: 'staging', duration: 30, priority: 'high', completed: false, order: 2, categoryId: 'cat1' },
    ];
  });

  const [mealPlans, setMealPlans] = useState<Record<string, DailyMeals>>({});
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [dailyNotes, setDailyNotes] = useState<Record<string, string>>({});
  const [journalEntries, setJournalEntries] = useState<JournalEntry[]>([]);

  const [shoppingCategories, setShoppingCategories] = useState<ShoppingCategory[]>([
    { id: 'shop_cat_1', name: 'Groceries', budget: 150, color: 'green' },
    { id: 'shop_cat_2', name: 'Home Improv', budget: 200, color: 'orange' }
  ]);
  const [shoppingItems, setShoppingItems] = useState<ShoppingItem[]>([
    { id: 'item_1', title: 'Milk', estimatedCost: 4.50, completed: false, categoryId: 'shop_cat_1' },
    { id: 'item_2', title: 'Eggs', estimatedCost: 6.00, completed: false, categoryId: 'shop_cat_1' },
    { id: 'item_3', title: 'Paint', estimatedCost: 45.00, completed: false, categoryId: 'shop_cat_2' },
  ]);

  const [activeNav, setActiveNav] = useState<'calendar' | 'meals' | 'shopping' | 'recurrence' | 'journal'>('calendar');

  const [activeId, setActiveId] = useState<string | null>(null);
  const [activeItem, setActiveItem] = useState<Task | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMealModalOpen, setIsMealModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [activeMealDate, setActiveMealDate] = useState<string | null>(null);
  const [isOptimizing, setIsOptimizing] = useState(false);
  const [viewMode, setViewMode] = useState<'today' | 'week' | 'month' | 'list'>('today');
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [sidebarTab, setSidebarTab] = useState<'backlog' | 'staging'>('staging');

  const today = startOfToday();
  const visibleDates = useMemo(() => {
    if (viewMode === 'month') {
      const monthStart = startOfMonth(today);
      const monthEnd = endOfMonth(today);
      const calendarStart = startOfWeek(monthStart);
      const calendarEnd = endOfWeek(monthEnd);
      return eachDayOfInterval({ start: calendarStart, end: calendarEnd });
    }
    if (viewMode === 'today') return [today];
    const daysToShow = 7;
    return Array.from({ length: daysToShow }).map((_, i) => addDays(today, i));
  }, [today, viewMode]);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  );

  const sidebarTasks = useMemo(() => 
    tasks
      .filter(t => t.scheduledDate === null && (t.stage || 'backlog') === sidebarTab)
      .sort((a, b) => a.order - b.order),
  [tasks, sidebarTab]);

  const getTasksForDate = (dateStr: string) => 
    tasks.filter(t => t.scheduledDate === dateStr).sort((a, b) => a.order - b.order);

  const spawnNextOccurrence = (task: Task): Task | null => {
    if (!task.recurrence || task.recurrence === 'none' || !task.scheduledDate) return null;
    let nextDate: Date;
    const currentDate = parseISO(task.scheduledDate);
    switch (task.recurrence) {
      case 'daily': nextDate = addDays(currentDate, 1); break;
      case 'weekly': nextDate = addWeeks(currentDate, 1); break;
      case 'monthly': nextDate = addMonths(currentDate, 1); break;
      default: return null;
    }
    return { ...task, id: uuidv4(), scheduledDate: format(nextDate, 'yyyy-MM-dd'), completed: false };
  };

  const handleCreateTask = (taskData: Partial<Task>) => {
    if (taskData.id) {
      setTasks(prev => prev.map(t => t.id === taskData.id ? { ...t, ...taskData } as Task : t));
    } else {
      const newTask: Task = {
        id: uuidv4(),
        title: taskData.title || 'Untitled',
        description: taskData.description,
        scheduledDate: taskData.scheduledDate || null, 
        stage: taskData.stage || sidebarTab,
        duration: taskData.duration || 30,
        priority: taskData.priority || 'medium',
        completed: false,
        order: sidebarTasks.length,
        categoryId: taskData.categoryId,
        startTime: taskData.startTime,
        recurrence: taskData.recurrence || 'none',
        recurrenceGroupId: taskData.recurrenceGroupId || (taskData.recurrence && taskData.recurrence !== 'none' ? uuidv4() : undefined)
      };
      setTasks(prev => [...prev, newTask]);
    }
  };

  const handleDeleteTask = (id: string) => setTasks(prev => prev.filter(t => t.id !== id));

  const handleToggleComplete = (id: string) => {
    setTasks(prev => {
      const target = prev.find(t => t.id === id);
      if (!target) return prev;
      const isBecomingComplete = !target.completed;
      const updatedTasks = prev.map(t => t.id === id ? { ...t, completed: isBecomingComplete } : t);
      if (isBecomingComplete && target.recurrence && target.recurrence !== 'none') {
        const nextTask = spawnNextOccurrence(target);
        if (nextTask) {
          const alreadyExists = updatedTasks.some(t => t.recurrenceGroupId === target.recurrenceGroupId && t.scheduledDate === nextTask.scheduledDate);
          if (!alreadyExists) return [...updatedTasks, nextTask];
        }
      }
      return updatedTasks;
    });
  };

  const handleMoveStage = (id: string, newStage: 'backlog' | 'staging') => {
    setTasks(prev => prev.map(t => t.id === id ? { ...t, stage: newStage } : t));
  };

  const handleAddCategory = (newCat: Category) => setCategories(prev => [...prev, newCat]);
  const handleDeleteCategory = (id: string) => {
    setCategories(prev => prev.filter(c => c.id !== id));
    setTasks(prev => prev.map(t => t.categoryId === id ? { ...t, categoryId: undefined } : t));
  };

  const handleOpenMealModal = (dateStr: string) => {
    setActiveMealDate(dateStr);
    setIsMealModalOpen(true);
  };

  const handleSaveMealPlan = (dateStr: string, meals: DailyMeals) => setMealPlans(prev => ({ ...prev, [dateStr]: meals }));
  const handleAddRecipe = (recipe: Recipe) => setRecipes(prev => [...prev, recipe]);
  const handleDeleteRecipe = (id: string) => setRecipes(prev => prev.filter(r => r.id !== id));

  const handleAddShoppingCategory = (cat: ShoppingCategory) => setShoppingCategories(prev => [...prev, cat]);
  const handleDeleteShoppingCategory = (id: string) => {
    setShoppingCategories(prev => prev.filter(c => c.id !== id));
    setShoppingItems(prev => prev.map(i => i.categoryId === id ? { ...i, categoryId: undefined } : i));
  };
  const handleAddShoppingItem = (item: ShoppingItem) => setShoppingItems(prev => [...prev, item]);
  const handleUpdateShoppingItem = (item: ShoppingItem) => setShoppingItems(prev => prev.map(i => i.id === item.id ? item : i));
  const handleDeleteShoppingItem = (id: string) => setShoppingItems(prev => prev.filter(i => i.id !== id));

  const handleOptimize = async () => {
    setIsOptimizing(true);
    const datesStr = visibleDates.slice(0, 7).map(d => format(d, 'yyyy-MM-dd'));
    try {
      const optimizedTasks = await optimizeSchedule(tasks, datesStr);
      setTasks(optimizedTasks);
    } catch (e) { console.error(e); } finally { setIsOptimizing(false); }
  };

  const handleDragStart = (event: DragStartEvent) => {
    const { active } = event;
    setActiveId(active.id as string);
    const task = tasks.find(t => t.id === active.id);
    setActiveItem(task || null);
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    setActiveId(null);
    setActiveItem(null);
    if (!over) return;

    const activeId = active.id as string;
    const overId = over.id as string;
    const activeTask = tasks.find(t => t.id === activeId);
    if (!activeTask) return;

    if (overId === TAB_BACKLOG) {
      setTasks(prev => prev.map(t => t.id === activeId ? { ...t, scheduledDate: null, stage: 'backlog', startTime: undefined } : t));
      setSidebarTab('backlog');
      return;
    }
    if (overId === TAB_STAGING) {
      setTasks(prev => prev.map(t => t.id === activeId ? { ...t, scheduledDate: null, stage: 'staging', startTime: undefined } : t));
      setSidebarTab('staging');
      return;
    }

    if (overId.includes('::')) {
      const [dateStr, hourStr] = overId.split('::');
      setTasks(prev => prev.map(t => t.id === activeId ? { ...t, scheduledDate: dateStr, startTime: `${hourStr}:00`, stage: 'staging' } : t));
      return;
    }

    let containerId: string | null = null;
    if (visibleDates.some(d => format(d, 'yyyy-MM-dd') === overId)) containerId = overId;
    else {
      const overTask = tasks.find(t => t.id === overId);
      if (overTask) containerId = overTask.scheduledDate;
    }

    const destinationTasks = tasks.filter(t => {
      if (containerId === null) return t.scheduledDate === null && (t.stage || 'backlog') === sidebarTab;
      return t.scheduledDate === containerId && (viewMode === 'month' ? true : !t.startTime);
    }).sort((a,b) => a.order - b.order);

    const activeIndex = destinationTasks.findIndex(t => t.id === activeId);
    const overIndex = destinationTasks.findIndex(t => t.id === overId);

    if (activeIndex !== -1 && overIndex !== -1 && activeIndex !== overIndex) {
      const newOrder = arrayMove(destinationTasks, activeIndex, overIndex);
      setTasks(prev => {
        const next = [...prev];
        newOrder.forEach((t, index) => {
          const originalIndex = next.findIndex(ot => ot.id === t.id);
          if (originalIndex !== -1) next[originalIndex].order = index;
        });
        return next;
      });
    } else {
      setTasks(prev => prev.map(t => t.id === activeId ? { ...t, scheduledDate: containerId, stage: containerId === null ? sidebarTab : 'staging', startTime: undefined, order: destinationTasks.length } : t));
    }
  };

  const handleCreateAtTime = (dateStr: string, startTime: string, duration: number) => {
    setEditingTask({
        id: '', 
        title: '', 
        scheduledDate: dateStr, 
        startTime, 
        duration, 
        priority: 'medium', 
        completed: false, 
        order: 0, 
        stage: 'staging'
    } as Task);
    setIsModalOpen(true);
  };

  const applyRitualChanges = (changes: RitualProposedChanges) => {
    const newTasks = changes.tasksToAdd.map(t => ({
      ...t,
      id: uuidv4(),
      duration: t.duration || 30,
      priority: t.priority || 'medium',
      completed: false,
      order: 0,
      stage: 'staging',
      scheduledDate: t.scheduledDate || null,
      startTime: t.startTime || undefined
    } as Task));

    setTasks(prev => {
      let next = [...prev];
      next = next.map(t => changes.tasksToComplete.includes(t.id) ? { ...t, completed: true } : t);
      next = next.filter(t => !changes.tasksToRemove.includes(t.id));
      return [...next, ...newTasks];
    });

    if (changes.mealsToUpdate) {
      setMealPlans(prev => ({
        ...prev,
        [changes.mealsToUpdate!.date]: changes.mealsToUpdate!.meals
      }));
    }
  };

  const handleSaveJournalEntry = (entry: JournalEntry) => {
    setJournalEntries(prev => {
      const exists = prev.find(e => e.id === entry.id);
      if (exists) {
        return prev.map(e => e.id === entry.id ? { ...entry, lastSaved: new Date().toISOString() } : e);
      }
      return [...prev, { ...entry, lastSaved: new Date().toISOString() }];
    });
  };

  const handleDeleteJournalEntry = (id: string) => {
    setJournalEntries(prev => prev.filter(e => e.id !== id));
  };

  return (
    <div className="flex h-screen w-full bg-slate-200 text-slate-800 font-sans overflow-hidden">
      <div className="w-16 bg-white border-r border-slate-300 flex flex-col items-center py-6 gap-6 z-30 flex-shrink-0 shadow-md">
        <button onClick={() => setActiveNav('calendar')} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${activeNav === 'calendar' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'text-slate-400 hover:text-indigo-600 hover:bg-indigo-50'}`} title="Calendar"><CalendarIcon size={20} /></button>
        <button onClick={() => setActiveNav('journal')} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${activeNav === 'journal' ? 'bg-amber-500 text-white shadow-lg shadow-amber-200' : 'text-slate-400 hover:text-amber-600 hover:bg-amber-50'}`} title="Journal"><PenTool size={20} /></button>
        <button onClick={() => setActiveNav('recurrence')} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${activeNav === 'recurrence' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'text-slate-400 hover:text-indigo-600 hover:bg-indigo-50'}`} title="Recurring Tasks"><Repeat size={20} /></button>
        <button onClick={() => setActiveNav('meals')} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${activeNav === 'meals' ? 'bg-green-600 text-white shadow-lg shadow-green-200' : 'text-slate-400 hover:text-green-600 hover:bg-green-50'}`} title="Meal Plans"><Utensils size={20} /></button>
        <button onClick={() => setActiveNav('shopping')} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${activeNav === 'shopping' ? 'bg-rose-600 text-white shadow-lg shadow-rose-200' : 'text-slate-400 hover:text-rose-600 hover:bg-rose-50'}`} title="Shopping & Budget"><ShoppingCart size={20} /></button>
        <div className="mt-auto flex flex-col gap-4 w-full items-center">
            <button onClick={() => setSidebarOpen(!sidebarOpen)} className={`p-2 rounded-lg transition-colors ${sidebarOpen ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}>{sidebarOpen ? <ChevronLeft size={20} /> : <ChevronRight size={20} />}</button>
        </div>
      </div>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragStart={handleDragStart} onDragEnd={handleDragEnd}>
        <div className="flex flex-1 overflow-hidden relative">
          {activeNav === 'calendar' && (
            <div className={`bg-slate-50 border-r border-slate-300 flex flex-col z-20 shadow-lg transition-all duration-300 ease-in-out overflow-hidden whitespace-nowrap ${sidebarOpen ? 'w-80 opacity-100' : 'w-0 opacity-0 border-none'}`}>
              <div className="p-5 pb-0 flex-shrink-0">
                  <div className="flex justify-between items-center mb-4">
                    <h2 className="font-bold text-slate-800 text-lg">Tasks</h2>
                    <button 
                      onClick={() => { setEditingTask(null); setIsModalOpen(true); }} 
                      className="group flex items-center gap-1.5 bg-indigo-600 hover:bg-indigo-700 text-white px-3 py-1.5 rounded-full transition-all shadow-sm"
                    >
                      <Plus size={16} /> 
                      <span className="text-xs font-bold uppercase tracking-wide">Quick Add</span>
                    </button>
                  </div>
                  <div className="flex gap-4 border-b border-slate-200">
                    <DroppableTab id={TAB_STAGING} active={sidebarTab === 'staging'} onClick={() => setSidebarTab('staging')} icon={Inbox}>Staging</DroppableTab>
                    <DroppableTab id={TAB_BACKLOG} active={sidebarTab === 'backlog'} onClick={() => setSidebarTab('backlog')} icon={Layers}>Backlog</DroppableTab>
                  </div>
              </div>
              <div className="flex-1 overflow-hidden bg-slate-100 mt-2">
                  <DroppableContainer id={`sidebar-${sidebarTab}`} title={sidebarTab === 'staging' ? "Ready to Schedule" : "Unsorted Ideas"} tasks={sidebarTasks} categories={categories} onEditTask={(t) => { setEditingTask(t); setIsModalOpen(true); }} onDeleteTask={handleDeleteTask} onToggleComplete={handleToggleComplete} onMoveStage={handleMoveStage} isBacklog />
              </div>
            </div>
          )}

          <div className="flex-1 flex flex-col min-w-0 bg-white h-full shadow-inner">
            {activeNav === 'journal' ? (
              <JournalDashboard 
                entries={journalEntries} 
                onSaveEntry={handleSaveJournalEntry} 
                onDeleteEntry={handleDeleteJournalEntry}
                onApplyRitualChanges={applyRitualChanges}
                currentTasks={tasks}
              />
            ) : activeNav === 'recurrence' ? (
              <RecurrenceDashboard tasks={tasks} categories={categories} onEditTask={(t) => { setEditingTask(t); setIsModalOpen(true); }} onDeleteTask={handleDeleteTask} />
            ) : activeNav === 'meals' ? (
               <MealDashboard recipes={recipes} mealPlans={mealPlans} onAddRecipe={handleAddRecipe} onDeleteRecipe={handleDeleteRecipe} onEditDailyMeal={handleOpenMealModal} />
            ) : activeNav === 'shopping' ? (
                <ShoppingDashboard categories={shoppingCategories} items={shoppingItems} onAddCategory={handleAddShoppingCategory} onDeleteCategory={handleDeleteShoppingCategory} onAddItem={handleAddShoppingItem} onUpdateItem={handleUpdateShoppingItem} onDeleteItem={handleDeleteShoppingItem} />
            ) : (
              <>
                <div className="h-16 border-b border-slate-300 bg-white px-6 flex justify-between items-center flex-shrink-0 z-20">
                  <div className="flex items-center gap-6">
                    <h1 className="text-xl font-bold text-slate-800">{format(today, 'MMMM yyyy')}</h1>
                    <div className="flex bg-slate-100 p-1 rounded-lg border border-slate-200 shadow-sm">
                      <button onClick={() => setViewMode('today')} className={`flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-md transition-all ${viewMode === 'today' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}><LayoutDashboard size={14} /> Today</button>
                      <button onClick={() => setViewMode('week')} className={`flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-md transition-all ${viewMode === 'week' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}><CalendarDays size={14} /> Week</button>
                      <button onClick={() => setViewMode('month')} className={`flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-md transition-all ${viewMode === 'month' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}><Grid3X3 size={14} /> Month</button>
                      <button onClick={() => setViewMode('list')} className={`flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-md transition-all ${viewMode === 'list' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}><List size={14} /> Task View</button>
                    </div>
                  </div>
                  <button onClick={handleOptimize} disabled={isOptimizing} className="flex items-center gap-2 bg-indigo-700 hover:bg-indigo-800 text-white px-4 py-2 rounded-lg text-sm font-bold shadow-md transition-all disabled:opacity-70 disabled:cursor-not-allowed">
                    {isOptimizing ? <Loader2 className="animate-spin" size={16} /> : <Sparkles size={16} />} Smart Schedule
                  </button>
                </div>

                <div className="flex-1 overflow-hidden flex bg-slate-50">
                  <div className="flex-1 overflow-y-auto scrollbar-thin relative h-full">
                    {viewMode === 'list' ? (
                        <div className="max-w-3xl mx-auto w-full p-8 pb-32">
                            {Object.entries(tasks.filter(t => t.scheduledDate !== null).reduce((groups, task) => {
                                const date = task.scheduledDate!;
                                if (!groups[date]) groups[date] = [];
                                groups[date].push(task);
                                return groups;
                            }, {} as Record<string, Task[]>)).sort(([dateA], [dateB]) => dateA.localeCompare(dateB)).map(([dateStr, dayTasks]) => (
                                <div key={dateStr} className="mb-8">
                                    <h3 className="text-sm font-bold text-slate-500 uppercase tracking-widest mb-3 border-b border-slate-300 pb-2">{format(parseISO(dateStr), 'EEEE, MMMM d')}</h3>
                                    <DroppableContainer id={dateStr} title="" tasks={dayTasks} categories={categories} onEditTask={(t) => { setEditingTask(t); setIsModalOpen(true); }} onDeleteTask={handleDeleteTask} onToggleComplete={handleToggleComplete} compactMode />
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className={`flex h-full min-h-0 ${viewMode === 'month' ? 'grid grid-cols-7 auto-rows-fr bg-slate-200 gap-px border-b border-slate-300' : `divide-x divide-slate-300 ${viewMode === 'week' ? 'min-w-[1960px]' : 'w-full'}`}`}>
                            {viewMode === 'month' && ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(d => (
                                <div key={d} className="py-2 text-center text-xs font-bold text-slate-500 uppercase tracking-wider bg-slate-50 border-b border-slate-200">{d}</div>
                            ))}
                            {visibleDates.map(date => {
                                const dateStr = format(date, 'yyyy-MM-dd');
                                const isToday = isSameDay(date, today);
                                return (
                                    <div key={dateStr} className={viewMode === 'month' ? 'min-h-[140px] bg-white flex flex-col' : 'flex-1 min-w-[300px] h-full bg-white shadow-sm'}>
                                        <DroppableContainer 
                                            id={dateStr} 
                                            title={viewMode === 'month' ? format(date, 'd') : (isToday ? 'Today' : format(date, 'EEEE'))} 
                                            subtitle={viewMode === 'month' ? undefined : format(date, 'MMM d')} 
                                            isToday={isToday} 
                                            tasks={getTasksForDate(dateStr)} 
                                            categories={categories} 
                                            mealPlan={mealPlans[dateStr]} 
                                            onEditTask={(t) => { setEditingTask(t); setIsModalOpen(true); }} 
                                            onDeleteTask={handleDeleteTask} 
                                            onToggleComplete={handleToggleComplete} 
                                            onEditMealPlan={() => handleOpenMealModal(dateStr)} 
                                            compactMode={viewMode === 'month'}
                                            onCreateAtTime={handleCreateAtTime}
                                        />
                                    </div>
                                );
                            })}
                        </div>
                    )}
                  </div>
                  {viewMode === 'today' && (
                    <TodaySidebar 
                        tasks={tasks}
                        shoppingCategories={shoppingCategories}
                        shoppingItems={shoppingItems}
                        notes={dailyNotes[format(today, 'yyyy-MM-dd')] || ''}
                        onSaveNotes={(n) => setDailyNotes(prev => ({ ...prev, [format(today, 'yyyy-MM-dd')]: n }))}
                    />
                  )}
                </div>
              </>
            )}
          </div>
        </div>
        <DragOverlay>{activeItem ? (<div className="w-[280px] opacity-90 cursor-grabbing"><div className="transform rotate-2 shadow-2xl"><TaskCard task={activeItem} categoryData={categories.find(c => c.id === activeItem.categoryId)} onEdit={() => {}} onDelete={() => {}} onToggleComplete={() => {}} /></div></div>) : null}</DragOverlay>
      </DndContext>
      <TaskModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={handleCreateTask} 
        editingTask={editingTask} 
        categories={categories} 
        tasks={tasks}
        onAddCategory={handleAddCategory} 
        onDeleteCategory={handleDeleteCategory} 
      />
      <MealModal isOpen={isMealModalOpen} onClose={() => setIsMealModalOpen(false)} dateStr={activeMealDate} existingMeals={activeMealDate ? mealPlans[activeMealDate] : undefined} onSave={handleSaveMealPlan} />
    </div>
  );
}
